INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('a5ee6e90923eeab380e6730f674240d2', '1758906517.912099', 'C0880U9751A', 'message', 'EMPLOYEE_0002_SLACK_ID', '<@EMPLOYEE_0026_SLACK_ID> fyi the models you got out of unity on thursday are the text kind, the setting was wrong that day so youll need to redo them. they open fine in unity and in max so you wouldnt notice. the ones from <@EMPLOYEE_0009_SLACK_ID> are ok', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-26T17:08:37.912099Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('1d55b38831d7517fe403e4f2a906a897', '1758922879.243189', 'C08R8CHB0QL', 'message', 'EMPLOYEE_0016_SLACK_ID', 'Fun one. Let''s have it in the 8 in place of the last one on my list, we''ve got enough things that go boom. As it is now, the arrow can be its own item later.', '088b096edb82a130771a5da3344bcef1', '1758904025.123869', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-26T21:41:19.243189Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('da6776f77288224ec67847a799bbde5a', '1758823946.262829', 'C090N54TG79', 'message', 'EMPLOYEE_0016_SLACK_ID', 'For the playable board, the 8: Grenade, Couch and Plushie Chick from the reference level, plus Shuriken, Cute Axe, Gift Box, Cactus Plant and Dynamite. Everything else <@EMPLOYEE_0026_SLACK_ID> sends them is extras they can swap in.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-25T18:12:26.262829Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('0b7f656a96c5cc50d1f6924e089bf8ba', '1759167068.371289', 'C090N54TG79', 'message', 'EMPLOYEE_0016_SLACK_ID', '<@EMPLOYEE_0026_SLACK_ID> for PlayableX''s question, in case we carry on with them: one animation, walk. The 4 zombies: Party Girl, Plumber, Magician, Football Player. All four are in the pack Marcus sent.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-29T17:31:08.371289Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('8a1b1c6d448eecb7ccc81f796c95d5ce', '1759178332.042459', 'D05GU6L0XFH', 'message', 'EMPLOYEE_0016_SLACK_ID', 'btw <@EMPLOYEE_0009_SLACK_ID> is redoing the UVs on the bathroom objects from scratch, so the old ones will show in the levels for a bit. the bathroom files she gave <@EMPLOYEE_0026_SLACK_ID> on Friday are the old version too', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-29T20:38:52.042459Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('7e84f1cf59f8e95fef961268fbf37cc1', '1759256494.852159', 'D05SD5QLG94', 'message', 'EMPLOYEE_0008_SLACK_ID', 'Julia, PlayableX are holding Nov 3 for us and I don''t want a third slip on our side. While it''s parked, can you do for this one what you did for the Dominoes playable: write the brief they build from, and tell me where the item pack actually stands. Brian''s pack list is where it starts. Robert''s picks for the board and the zombies stand unless he''s changed them since. My hand-off notes say what goes in the brief, what counts as ready, what to do with the tickets and who gets the files. Write it for the game as it is today; if the core changes we redo that part with them in November. Brief as a doc and the hand-off list as a sheet, both in your Drive. Then give me the count for each state here, and post both links in the PlayableX channel so they know what''s still coming from us.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T18:21:34.852159Z', '{}');
INSERT INTO linear.linear_issues (id, uuid, project_id, team_id, parent_id, assignee_id, creator_id, state_id, cycle_id, identifier, number, title, description, priority, estimate, due_date, started_at, completed_at, canceled_at, archived_at, time_in_status_minutes, labels_json, links_json, relations_json, state_history_json, is_archived, created_at, updated_at) VALUES ('DES-313', NULL, NULL, 'team_DES', NULL, 'usr_fc22d5941b2aeb5c', 'usr_fc22d5941b2aeb5c', 'In Progress', NULL, 'DES-313', 313, 'Playable pack for PlayableX', 'Frederick wants every line of the playable pack tracked after the start slipped. One sub-ticket per line of the pack list, kept in Design so it stays off the ZM3D board. I leave a note on each one saying what I did with it. A line''s ticket closes when PlayableX have the file.', 0, NULL, NULL, '2025-09-25T07:21:48Z', NULL, NULL, NULL, NULL, '[]', '[]', '[]', '[]', false, '2025-09-25T07:05:12Z', '2025-09-25T07:21:48Z');
