VALUES ('f_faf4d7c167d14a1127dcc3', 'Outgoing folder - what''s in it', 'application/vnd.google-apps.document', '["d_fc22d5941b2aeb5c03ad32"]', 'brian.foster@harmonygames.co', '["frederick.stone@harmonygames.co", "julia.lawson@harmonygames.co"]', '[{"email": "frederick.stone@harmonygames.co", "role": "reader"}, {"email": "julia.lawson@harmonygames.co", "role": "reader"}]', 'private', '["brian.foster@harmonygames.co"]', '2025-09-30T09:12:26Z', '2025-09-25T15:58:14Z', false, false);
